(()=>{
 const P=Planning,phases=['Discovery','Design','Development','Launch'];
 const people=['Kiara Laras','Joe Tesla','Tania Brooks','Cameron Williamson','Bin Li'];
 const seeds=[['Development','2026-09-23','2026-09-30','Kiara Laras'],['Design','2026-09-24','2026-09-27','Joe Tesla'],['Development','2026-09-26','2026-10-02','Kiara Laras'],['Design','2026-09-28','2026-10-04','Tania Brooks']];
 issues.forEach((t,i)=>Object.assign(t,{projectId:'REV-241',phase:seeds[i][0],startDate:seeds[i][1],endDate:seeds[i][2],assignee:seeds[i][3]}));
 issues.push({id:'RFC-106',name:'Map customer reporting needs',status:'Done',projectId:'REV-241',phase:'Discovery',startDate:'2026-09-18',endDate:'2026-09-22',assignee:'Tania Brooks'}, {id:'ONB-201',name:'Audit the current onboarding journey',status:'Done',projectId:'ONB-118',phase:'Discovery',startDate:'2026-09-20',endDate:'2026-09-24',assignee:'Cameron Williamson'}, {id:'ONB-202',name:'Design the welcome checklist',status:'In Progress',projectId:'ONB-118',phase:'Design',startDate:'2026-09-25',endDate:'2026-10-01',assignee:'Joe Tesla'}, {id:'ONB-203',name:'Build account setup screens',status:'Todo',projectId:'ONB-118',phase:'Development',startDate:'2026-10-02',endDate:'2026-10-07',assignee:'Kiara Laras'}, {id:'ONB-204',name:'Prepare onboarding release',status:'Backlog',projectId:'ONB-118',phase:'Launch',startDate:'2026-10-08',endDate:'2026-10-09',assignee:'Tania Brooks'});
 let view='overview',projectFilter='all',query='',zoom=36,editing=null,dragging=null;const closed=new Set();
 const main=$('main'),overview=[...main.children].filter(el=>el.tagName!=='FOOTER');
 const surface=document.createElement('section');surface.id='planning';surface.className='hidden';surface.innerHTML=`<div class="planning-title"><div><p class="eyebrow">PROJECT PLANNING</p><h1 id="planning-title"></h1><p id="planning-description" class="muted"></p></div><button class="primary" id="add-task">+ Add task</button></div><div class="planning-toolbar"><div class="plan-tabs" role="tablist" aria-label="Planning views"><button role="tab" data-switch="wbs">Work breakdown</button><button role="tab" data-switch="kanban">Kanban</button><button role="tab" data-switch="gantt">Gantt chart</button></div><div class="plan-filters"><label class="sr-only" for="plan-project">Filter by project</label><select id="plan-project"></select><label class="search">⌕ <input id="task-search" placeholder="Find a task…" aria-label="Find a task"></label></div></div><div id="plan-summary"></div><div id="plan-content"></div><p class="planning-help">Shared tasks across all three views · Sample workspace · Changes last for this session</p>`;main.insertBefore(surface,$('footer'));
 const editor=document.createElement('dialog');editor.id='task-editor';editor.setAttribute('aria-labelledby','task-editor-title');editor.innerHTML=`<form id="task-form"><div class="panel-heading"><h2 id="task-editor-title">New task</h2><button type="button" data-close-task class="icon-btn" aria-label="Close task editor">×</button></div><div class="task-fields"><label for="task-name">Task name</label><input id="task-name" name="name" required maxlength="120"><div class="field-grid"><div><label for="task-project">Project</label><select id="task-project" name="projectId" required></select></div><div><label for="task-phase">Work package</label><select id="task-phase" name="phase">${phases.map(p=>`<option>${p}</option>`).join('')}</select></div><div><label for="task-status">Status</label><select id="task-status" name="status">${P.statuses.map(p=>`<option>${p}</option>`).join('')}</select></div><div><label for="task-assignee">Assignee</label><select id="task-assignee" name="assignee">${people.map(p=>`<option>${p}</option>`).join('')}</select></div><div><label for="task-start">Start date</label><input type="date" id="task-start" name="startDate" required min="2000-01-01" max="2100-12-31"></div><div><label for="task-end">End date</label><input type="date" id="task-end" name="endDate" required min="2000-01-01" max="2100-12-31"></div></div><p id="task-error" role="alert"></p></div><div class="dialog-actions"><button type="button" class="secondary" data-close-task>Cancel</button><button class="primary" type="submit">Save task</button></div></form>`;document.body.append(editor);
 const initials=name=>name.split(' ').map(n=>n[0]).join('');
 const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
 const filtered=()=>issues.filter(t=>(projectFilter==='all'||t.projectId===projectFilter)&&(!query||(t.name+' '+t.id+' '+t.assignee).toLowerCase().includes(query)));
 const statusSelect=t=>`<select class="task-status ${P.colors[t.status]}" data-status="${t.id}" aria-label="Status for ${esc(t.name)}">${P.statuses.map(s=>`<option${s===t.status?' selected':''}>${s}</option>`).join('')}</select>`;
 const meter=tasks=>`<span class="rollup"><span class="progress-track"><i style="width:${P.progress(tasks)}%"></i></span>${P.progress(tasks)}%</span>`;
 function projectOptions(selected,all=false){return (all?'<option value="all">All projects</option>':'')+projects.map(p=>`<option value="${p.id}"${p.id===selected?' selected':''}>${esc(p.name)}</option>`).join('')}
 function show(next){view=next;overview.forEach(el=>el.classList.toggle('hidden',next!=='overview'));surface.classList.toggle('hidden',next==='overview');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',next==='overview'?b.dataset.view==='overview':b.dataset.plan===next));$('#crumb').textContent=next==='overview'?'Dashboard':{wbs:'Work breakdown',kanban:'Kanban board',gantt:'Gantt chart'}[next];$('#search').closest('.search').classList.toggle('hidden',next!=='overview');if(next!=='overview')draw();if(innerWidth<980)document.body.classList.remove('collapsed');window.scrollTo({top:0,behavior:'instant'})}
 function draw(){if(view==='overview')return;$('#planning-title').textContent={wbs:'Work breakdown structure',kanban:'Kanban board',gantt:'Gantt chart'}[view];$('#planning-description').textContent={wbs:'Organize deliverables into projects, work packages, and tasks.',kanban:'Move work forward, one task at a time.',gantt:'Plan dates and see how work fits together.'}[view];$('#plan-project').innerHTML=projectOptions(projectFilter,true);$('#plan-project').value=projectFilter;document.querySelectorAll('[data-switch]').forEach(b=>{b.classList.toggle('active',b.dataset.switch===view);b.setAttribute('aria-selected',b.dataset.switch===view)});let tasks=filtered();$('#plan-summary').innerHTML=`<span><b>${tasks.length}</b> tasks</span><span><b>${tasks.filter(t=>t.status==='In Progress').length}</b> in progress</span><span><b>${tasks.filter(t=>t.status==='Done').length}</b> completed</span>${meter(tasks)}`;if(view==='wbs')drawWbs(tasks);if(view==='kanban')drawKanban(tasks);if(view==='gantt')drawGantt(tasks)}
 function drawWbs(tasks){let html='<div class="panel wbs"><div class="wbs-top"><span>DELIVERABLE / TASK</span><button class="secondary" id="expand-wbs">Expand all</button><button class="secondary" id="collapse-wbs">Collapse all</button></div>';projects.filter(p=>projectFilter==='all'||p.id===projectFilter).forEach(p=>{let pTasks=tasks.filter(t=>t.projectId===p.id);if(query&&!pTasks.length)return;let pn=projects.indexOf(p)+1,pClosed=closed.has(p.id);html+=`<div class="wbs-project"><div class="wbs-row group"><button class="tree-toggle" data-toggle="${p.id}" aria-expanded="${!pClosed}" aria-label="${pClosed?'Expand':'Collapse'} ${esc(p.name)}">${pClosed?'▸':'▾'}</button><span class="wbs-number">${pn}</span><strong>${esc(p.name)}</strong><span class="count">${pTasks.length} tasks</span>${meter(pTasks)}</div>`;if(!pClosed)phases.forEach((phase,pi)=>{let key=p.id+'-'+pi,children=pTasks.filter(t=>t.phase===phase),isClosed=closed.has(key);if(query&&!children.length)return;html+=`<div class="wbs-row phase"><button class="tree-toggle" data-toggle="${key}" aria-expanded="${!isClosed}" aria-label="${isClosed?'Expand':'Collapse'} ${esc(p.name+' '+phase)}">${isClosed?'▸':'▾'}</button><span class="wbs-number">${pn}.${pi+1}</span><strong>${phase}</strong><span class="count">${children.length}</span>${meter(children)}<button class="text-btn" data-package="${p.id}" data-phase="${phase}" aria-label="Add task to ${esc(p.name+' '+phase)}">+ Add task</button></div>`;if(!isClosed)children.forEach((t,ti)=>{html+=`<div class="wbs-row task"><span class="wbs-number">${pn}.${pi+1}.${ti+1}</span><button class="task-title" data-edit="${t.id}">${esc(t.name)}<small>${t.id} · ${esc(t.assignee)} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></button>${statusSelect(t)}</div>`})});html+='</div>'});html+='</div>';$('#plan-content').innerHTML=html+(query&&!tasks.length?'<p class="empty">No tasks match your search.</p>':'')}
 function drawKanban(tasks){$('#plan-content').innerHTML=`<p class="board-hint">Drag cards between columns, or use a card’s status menu.</p><div class="kanban-board">${P.statuses.map(s=>{let column=tasks.filter(t=>t.status===s);return `<section class="kanban-column" data-drop="${s}" aria-label="${s} column"><div class="column-title"><span><i class="dot ${P.colors[s]}"></i>${s}</span><span class="count">${column.length}</span></div><div class="column-cards">${column.map(t=>`<article class="kanban-card" draggable="true" data-drag="${t.id}"><span class="card-id">${t.id} · ${esc(t.phase)}</span><button class="task-title" data-edit="${t.id}">${esc(t.name)}</button><p class="card-project">${esc(projects.find(p=>p.id===t.projectId)?.name||'')}</p><div class="card-meta"><span class="avatar" title="${esc(t.assignee)}">${initials(t.assignee)}</span><time>${dateLabel(t.endDate)}</time></div>${statusSelect(t)}</article>`).join('')||'<div class="empty-column">No tasks here</div>'}</div><button class="add-column-task" data-new-status="${s}">+ Add task</button></section>`}).join('')}</div>`}
 function drawGantt(tasks){if(!tasks.length){$('#plan-content').innerHTML='<div class="panel empty">No tasks match your filters. Add a task or adjust your search.</div>';return;}let b=P.bounds(tasks),width=b.days*zoom;let ticks='';for(let d=0;d<b.days;d++){let date=P.iso(b.start+d),weekday=new Date(date+'T12:00:00Z').getUTCDay();ticks+=`<div class="gantt-day ${weekday===0||weekday===6?'weekend':''}" style="width:${zoom}px">${zoom>=30?`<small>${dateLabel(date).split(' ')[0]}</small>${Number(date.slice(-2))}`:d%7===0?dateLabel(date):''}</div>`}let today=P.day(new Date().toISOString().slice(0,10)),todayMarker=today>=b.start&&today<=b.end?`<span class="today-marker" style="left:${(today-b.start)*zoom+zoom/2}px" title="Today"></span>`:'';$('#plan-content').innerHTML=`<div class="gantt-tools"><span>${dateLabel(P.iso(b.start))}, ${P.iso(b.start).slice(0,4)} – ${dateLabel(P.iso(b.end))}, ${P.iso(b.end).slice(0,4)}</span><div><label for="gantt-zoom">Scale</label> <select id="gantt-zoom"><option value="36"${zoom===36?' selected':''}>Day</option><option value="14"${zoom===14?' selected':''}>Week</option></select></div></div><div class="panel gantt-scroll" tabindex="0" aria-label="Gantt chart, scroll horizontally for more dates"><div class="gantt-table" style="width:${width+280}px;--day-width:${zoom}px"><div class="gantt-row gantt-header"><div class="gantt-label">TASK / SCHEDULE</div><div class="gantt-track" style="width:${width}px">${ticks}</div></div>${tasks.map(t=>`<div class="gantt-row"><button class="gantt-label" data-edit="${t.id}"><strong>${esc(t.name)}</strong><small>${t.id} · ${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></button><div class="gantt-track grid-track" style="width:${width}px">${todayMarker}<button class="gantt-bar ${P.colors[t.status]}" data-edit="${t.id}" style="left:${(P.day(t.startDate)-b.start)*zoom+2}px;width:${(P.day(t.endDate)-P.day(t.startDate)+1)*zoom-4}px" aria-label="Edit ${esc(t.name)}, ${t.startDate} to ${t.endDate}, ${t.status}" title="${esc(t.name)} · ${t.startDate} to ${t.endDate} · ${t.status}">${esc(t.name)}</button></div></div>`).join('')}</div></div><div class="gantt-legend">${P.statuses.map(s=>`<span><i class="dot ${P.colors[s]}"></i>${s}</span>`).join('')}<span>Click a task to edit dates</span></div>`}
 function openTask(id,defaults={}){editing=id||null;let task=issues.find(t=>t.id===id)||{name:'',projectId:projectFilter==='all'?projects[0].id:projectFilter,phase:'Development',status:'Todo',assignee:'Bin Li',startDate:new Date().toISOString().slice(0,10),endDate:new Date().toISOString().slice(0,10),...defaults};$('#task-editor-title').textContent=id?'Edit task · '+id:'New task';$('#task-project').innerHTML=projectOptions(task.projectId);for(let name of ['name','phase','status','assignee','startDate','endDate'])$('#task-form').elements[name].value=task[name];$('#task-error').textContent='';editor.showModal();$('#task-name').focus()}
 function changed(message){issues.forEach(t=>t.color=P.colors[t.status]);render();draw();toast(message)}
 function setStatus(id,status){let t=issues.find(t=>t.id===id);if(!t||!P.statuses.includes(status)||t.status===status)return;t.status=status;changed(t.id+' moved to '+status)}
 function syncOverview(){
 $('#stats').innerHTML=[['Total Projects',projects.length,'Projects in this workspace'],['Total Tasks',issues.length,'Shared planning tasks'],['In Progress',issues.filter(t=>t.status==='In Progress').length,'Tasks underway'],['Completed',issues.filter(t=>t.status==='Done').length,'Tasks delivered']].map(([label,value,desc])=>`<article class="stat"><div class="stat-label">${label}</div><strong>${value}</strong><small>${desc}</small></article>`).join('');
 document.querySelector('[data-view="projects"] small').textContent=projects.length;document.querySelector('[data-view="issues"] small').textContent=issues.length;
 let counts=P.statuses.map(s=>issues.filter(t=>t.status===s).length),palette=['#dadce2','#9ecddf','#e1c775','#b9a2d8','#98b5a4'],offset=0;
 let stops=counts.map((n,i)=>{let start=offset;offset+=n/issues.length*100;return `${palette[i]} ${start}% ${offset}%`});
 $('.donut').style.background=`conic-gradient(${stops.join(',')})`;$('.donut>span').innerHTML=`${issues.length}<small>Total issues</small>`;
 $('.legend').innerHTML=P.statuses.map((s,i)=>`<p><i class="dot ${P.colors[s]}"></i>${s}<b>${counts[i]}</b></p>`).join('');$('.status-chart').previousElementSibling.querySelector('.count').textContent=issues.length+' issues';
 }
 const baseRender=render;render=function(){baseRender();syncOverview();if(view!=='overview')draw()};
 const originalCreate=openCreate;openCreate=function(t){if(t==='issue')openTask();else originalCreate(t)};
 // The overview's issue map uses the same editable task records.
 document.addEventListener('click',e=>{let issue=e.target.closest('[data-issue]');if(issue){e.stopImmediatePropagation();openTask(issues[Number(issue.dataset.issue)].id)}},true);
 document.querySelectorAll('nav [data-view]').forEach(b=>{let original=b.onclick;b.onclick=()=>{show('overview');original()}});
 document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>show(b.dataset.plan));
 surface.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.switch)show(b.dataset.switch);if(b.dataset.edit)openTask(b.dataset.edit);if(b.dataset.toggle){let key=b.dataset.toggle;closed.has(key)?closed.delete(key):closed.add(key);draw()}if(b.dataset.package)openTask(null,{projectId:b.dataset.package,phase:b.dataset.phase});if(b.dataset.newStatus)openTask(null,{status:b.dataset.newStatus});if(b.id==='add-task')openTask();if(b.id==='expand-wbs'){closed.clear();draw()}if(b.id==='collapse-wbs'){projects.forEach(p=>closed.add(p.id));draw()}});
 surface.addEventListener('change',e=>{if(e.target.dataset.status)setStatus(e.target.dataset.status,e.target.value);if(e.target.id==='plan-project'){projectFilter=e.target.value;draw()}if(e.target.id==='gantt-zoom'){zoom=Number(e.target.value);draw()}});
 $('#task-search').oninput=e=>{query=e.target.value.toLowerCase().trim();draw()};
 surface.addEventListener('dragstart',e=>{let card=e.target.closest('[data-drag]');if(!card)return;dragging=card.dataset.drag;e.dataTransfer.setData('text/plain',dragging);e.dataTransfer.effectAllowed='move';card.classList.add('dragging')});
 surface.addEventListener('dragover',e=>{let column=e.target.closest('[data-drop]');if(!column||!dragging)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));column.classList.add('drop-target')});
 surface.addEventListener('drop',e=>{let column=e.target.closest('[data-drop]');if(!column||!dragging)return;e.preventDefault();setStatus(dragging,column.dataset.drop);dragging=null});surface.addEventListener('dragend',()=>{dragging=null;document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'))});
 editor.querySelectorAll('[data-close-task]').forEach(b=>b.onclick=()=>editor.close());
 $('#task-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.name=values.name.trim();let error=P.validate(values);if(error){$('#task-error').textContent=error;return;}let existing=issues.find(t=>t.id===editing);if(existing)Object.assign(existing,values);else{let id='TSK-'+(Math.max(300,...issues.map(t=>Number(t.id.split('-').pop())))+1);issues.push({...values,id,color:P.colors[values.status],start:10,width:65});newIssues++;}activity.unshift({initials:'BL',name:existing?'You updated a task':'You added a task',description:values.name,time:'Just now'});editor.close();changed(existing?'Task updated across all views':'Task added to all views')};
 // Keep the original timeline as a compact preview, with bars derived from dates.
 renderTimeline=function(){let tasks=issues, b=P.bounds(tasks);$('#timeline').innerHTML=`<div class="axis"><span>${dateLabel(P.iso(b.start))}</span><span>${dateLabel(P.iso(b.start+Math.floor(b.days/2)))}</span><span>${dateLabel(P.iso(b.end))}</span></div>`+tasks.slice(0,4).map((t,i)=>`<div class="issue-row"><div class="issue-name"><strong>${t.id}</strong>${t.status}</div><div class="track"><button class="bar ${P.colors[t.status]}" style="left:${(P.day(t.startDate)-b.start)/b.days*100}%;width:${(P.day(t.endDate)-P.day(t.startDate)+1)/b.days*100}%" data-issue="${i}" title="${esc(t.name)}"><span>${esc(t.name)}<small>${dateLabel(t.startDate)} – ${dateLabel(t.endDate)}</small></span></button></div></div>`).join('')};
 $('#range').innerHTML='<button id="full-gantt">Open Gantt</button>';$('#range').onclick=()=>show('gantt');issues.forEach(t=>t.color=P.colors[t.status]);render();
})();
